import pathlib,json,hashlib,collections
P=pathlib.Path(__file__).parent
m=json.loads((P/'capture-manifest.json').read_text());assert len(m['cases'])==120
checks=[];contracts=[]
units=json.loads((P/'root-unit-contexts.json').read_text())['contexts']
def resolved_spacing(r,case):
 token=r['roleTokens']['--mg-spacing-25'].strip();unit=units[case['brand']+'-'+case['script']+'-'+str(case['width'])];assert unit['spacingToken'].strip()==token
 if token.endswith('rem'):return format(float(token[:-3])*float(unit['rootFontSize'][:-2]),'g')+'px'
 return token
def rgb(value):return 'rgb('+', '.join(str(int(float(x))) for x in value.strip().replace(',', ' ').split())+')'
def check(case,field,expected,actual):
 checks.append({'case':case,'field':field,'expected':expected,'actual':actual,'passed':expected==actual})
for case in m['cases']:
 name=case['case'];raw=(P/'captures'/(name+'.json')).read_bytes();assert {'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}==case['json'];r=json.loads(raw);a,b=r['anchors'];ctx=r['previewContext'];check(name,'matching preview body class',[] if case['brand']=='undrr' else ['mg-theme-'+case['brand']],ctx['bodyClasses']);check(name,'actual I18n locale','ar' if case['script']=='arabic' else 'en',ctx['i18n']['locale']);check(name,'actual I18n direction','rtl' if case['script']=='arabic' else 'ltr',ctx['i18n']['direction']);check(name,'canvas direction','rtl' if case['script']=='arabic' else 'ltr',ctx['canvasDir']);check(name,'canvas language','ar' if case['script']=='arabic' else 'en',ctx['canvasLang']);check(name,'actual .menu li owner classes',['','selected'],[a['class'],b['class']]);check(name,'module href',['#','#'],[a['href'],b['href']]);check(name,'module tabIndex',['0','0'],[a['tabIndex'],b['tabIndex']]);check(name,'current caller supplied whole text',[r['arguments']['text']]*2,[a['text'],b['text']]);check(name,'source anchor inline display',['inline','inline'],[a['computed']['display'],b['computed']['display']]);check(name,'selected border width','2px',b['computed']['borderBottomWidth']);check(name,'selected border style','solid',b['computed']['borderBottomStyle']);check(name,'selected authored red role',rgb(r['roleTokens']['--mg-color-red-900']),b['computed']['borderBottomColor']);check(name,'selected source spacing padding',resolved_spacing(r,case),b['computed']['paddingBottom']);
 check(name,'Arabic versus Latin script direction','rtl' if case['script']=='arabic' else 'ltr',r['dir']);
 if case['script']=='arabic':check(name,'actual authored Arabic tracking','normal',a['computed']['letterSpacing'])
 for owner,anchor in [('default',a),('selected',b)]:
  if case['state']=='hover-'+owner:check(name,'actual pointer target hovered',True,anchor['hover']);check(name,'hover authored underline','underline',anchor['computed']['textDecorationLine']);check(name,'hover cursor','pointer',anchor['computed']['cursor']);check(name,'hover authored neutral role',rgb(r['roleTokens']['--mg-color-neutral-600']),anchor['computed']['color'])
  if case['state']=='focus-'+owner:check(name,'keyboard actual focus-visible',True,anchor['focusVisible']);check(name,'focus authored underline','underline',anchor['computed']['textDecorationLine']);check(name,'focus authored role color',rgb(r['roleTokens']['--mg-color-focus-ring']),anchor['computed']['outlineColor']);check(name,'focus outline width',r['roleTokens']['--mg-focus-ring-width'].strip(),anchor['computed']['outlineWidth']);check(name,'focus outline offset',r['roleTokens']['--mg-focus-ring-offset'].strip(),anchor['computed']['outlineOffset'])
 contracts.append({'case':name,'brand':case['brand'],'script':case['script'],'width':case['width'],'state':case['state'],'arguments':r['arguments'],'owners':[{'owner':x['owner'],'inlineBox':x['box'],'inlineFragments':x['fragments'],'textFragments':x['textFragments'],'computed':x['computed'],'hover':x['hover'],'focusVisible':x['focusVisible']} for x in r['anchors']],'loadedFonts':r['fonts'],'sourceRoleTokens':r['roleTokens'],'previewContext':ctx})
failed=[c for c in checks if not c['passed']];out={'matchingPreviewThemeAndI18nContexts':True,'notAuthoredStory':True,'controlledActualModuleContexts':True,'authoredStories':0,'rawCaptures':120,'controlledArgumentStates':['default','selected'],'scriptContexts':['english','arabic'],'brands':5,'viewportWidths':[390,1164],'sourceOwnerAnchors':240,'checks':len(checks),'failures':failed,'nativeAccepted':False,'scope':'Actual JSX and compiled CSS fixture evidence. No source-family/variant registration, actual package-export/caller inference or native browser pixel equivalence.'};(P/'source-contracts.json').write_text(json.dumps(contracts,ensure_ascii=False,indent=2)+'\n');(P/'audit-verdict.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps(out,ensure_ascii=False));assert not failed
